effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l = gmLum(c);
  vec3 grade = mix(colorA.rgb, colorB.rgb, l);
  vec3 col = mix(c, c * 0.4 + grade * 0.75, amount * mixAmt);
  float g = abs(fract(uv.y * gridRows - acTime * 0.3) - 0.5);
  float line = smoothstep(0.5, 0.46, g);
  col += colorB.rgb * line * gridAmt * smoothstep(0.4, 1.0, uv.y);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
